// Build a Markdown QA report for one run, plus a before/after table over all runs.
const settings = $('Settings').first().json;
const runId = settings.run_id;

// CSV files written by n8n start with an invisible BOM, which can stick to the first
// column name ("﻿run_id"). Remove it from every column name.
function clean(row) {
  const out = {};
  for (const key of Object.keys(row)) {
    out[key.replace(/^﻿/, '')] = row[key];
  }
  return out;
}

const allRows = [];
for (const item of $input.all()) {
  allRows.push(clean(item.json));
}

// Rows of the run this report is about.
const rows = [];
for (const row of allRows) {
  if (row.run_id === runId) {
    rows.push(row);
  }
}

const labelOrder = ['correct', 'wrong_answer', 'missing_content', 'retrieval_miss', 'dead_end', 'bad_escalation', 'made_up'];

function percent(part, total) {
  return (100 * part / total).toFixed(1) + '%';
}

// Count labels and remember which questions have each label.
const questionsByLabel = {};
for (const label of labelOrder) {
  questionsByLabel[label] = [];
}
for (const row of rows) {
  questionsByLabel[row.label].push(row.question_id);
}
const total = rows.length;
const correct = questionsByLabel['correct'].length;

const lines = [];
lines.push('# QA report: ' + runId);
lines.push('');
lines.push('Generated: ' + new Date().toISOString().slice(0, 16).replace('T', ' ') + ' UTC');
lines.push('');
lines.push('## Summary');
lines.push('');
lines.push('**Pass rate: ' + correct + ' / ' + total + ' (' + percent(correct, total) + ')** of the frozen test questions are labelled `correct`.');
lines.push('');

lines.push('## Labels');
lines.push('');
lines.push('| Label | Count | Questions |');
lines.push('|---|---|---|');
for (const label of labelOrder) {
  const ids = questionsByLabel[label];
  let shown = ids.join(', ');
  if (label === 'correct') {
    shown = '(not listed)';
  }
  lines.push('| ' + label + ' | ' + ids.length + ' | ' + shown + ' |');
}
lines.push('');

// Pass rate per category.
const categories = [];
const perCategory = {};
for (const row of rows) {
  if (!(row.category in perCategory)) {
    categories.push(row.category);
    perCategory[row.category] = { total: 0, correct: 0 };
  }
  perCategory[row.category].total = perCategory[row.category].total + 1;
  if (row.label === 'correct') {
    perCategory[row.category].correct = perCategory[row.category].correct + 1;
  }
}
lines.push('## Per category');
lines.push('');
lines.push('| Category | Questions | Correct | Pass rate |');
lines.push('|---|---|---|---|');
for (const category of categories) {
  const c = perCategory[category];
  lines.push('| ' + category + ' | ' + c.total + ' | ' + c.correct + ' | ' + percent(c.correct, c.total) + ' |');
}
lines.push('');

// Articles to fix: problems that point at the content of one article.
const articleLabels = ['wrong_answer', 'missing_content', 'retrieval_miss'];
const articles = [];
const problemsByArticle = {};
for (const row of rows) {
  if (articleLabels.includes(row.label)) {
    if (!(row.expected_article in problemsByArticle)) {
      articles.push(row.expected_article);
      problemsByArticle[row.expected_article] = [];
    }
    // A '|' would end a Markdown table cell, so it is escaped as '\\|'.
    const reason = row.reason.split('|').join('\\|');
    problemsByArticle[row.expected_article].push(row.question_id + ' ' + row.label + ': ' + reason);
  }
}
articles.sort();
lines.push('## Articles to fix');
lines.push('');
if (articles.length === 0) {
  lines.push('None.');
} else {
  lines.push('| Article | Problems |');
  lines.push('|---|---|');
  for (const article of articles) {
    lines.push('| ' + article + ' | ' + problemsByArticle[article].join('<br>') + ' |');
  }
}
lines.push('');

// Rules and settings: problems caused by the escalation keywords or the threshold.
lines.push('## Rules and settings to check');
lines.push('');
let ruleProblems = 0;
for (const row of rows) {
  if (row.label === 'bad_escalation' || row.label === 'dead_end') {
    lines.push('- ' + row.question_id + ' `' + row.label + '`: ' + row.reason);
    ruleProblems = ruleProblems + 1;
  }
}
if (ruleProblems === 0) {
  lines.push('None.');
}
lines.push('');

// Manual spot check: how many automatic labels the human reviewer agreed with.
let checked = 0;
let agreed = 0;
for (const row of rows) {
  if (row.spot_check === 'yes' && row.manual_label !== '') {
    checked = checked + 1;
    if (row.manual_label === row.label) {
      agreed = agreed + 1;
    }
  }
}
lines.push('## Manual spot check');
lines.push('');
if (checked === 0) {
  lines.push('Not done yet.');
} else {
  lines.push(agreed + ' of ' + checked + ' automatic labels confirmed by manual review.');
}
lines.push('');

// Before/after: one line per run found in data/labels_*.csv.
const runs = [];
for (const row of allRows) {
  if (!runs.includes(row.run_id)) {
    runs.push(row.run_id);
  }
}
runs.sort();
lines.push('## Before / after');
lines.push('');
let header = '| Run | Pass rate |';
let divider = '|---|---|';
for (const label of labelOrder) {
  header = header + ' ' + label + ' |';
  divider = divider + '---|';
}
lines.push(header);
lines.push(divider);
for (const run of runs) {
  const counts = {};
  let runTotal = 0;
  for (const label of labelOrder) {
    counts[label] = 0;
  }
  for (const row of allRows) {
    if (row.run_id === run) {
      counts[row.label] = counts[row.label] + 1;
      runTotal = runTotal + 1;
    }
  }
  let line = '| ' + run + ' | ' + counts['correct'] + '/' + runTotal + ' (' + percent(counts['correct'], runTotal) + ') |';
  for (const label of labelOrder) {
    line = line + ' ' + counts[label] + ' |';
  }
  lines.push(line);
}
lines.push('');

return [{ json: { report: lines.join('\n') } }];
